query ($criteria: HotelCriteriaQuoteInput!, $settings: HotelSettingsInput) {
  hotelX {
    quote(criteria: $criteria, settings: $settings) {
      errors { code type description }
      optionQuote {
        optionRefId
        hotelCode
        boardCode
        status
        paymentType
        cancelPolicy { refundable }
        price { net currency }
      }
    }
  }
}
